using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<ModelTrainingService>();
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>();

var app = builder.Build();

// Train the model at startup so the prediction pool has a model to load
var trainer = app.Services.GetRequiredService<ModelTrainingService>();
trainer.TrainAndEvaluate();
app.Services.GetRequiredService<Microsoft.Extensions.ML.PredictionEnginePool<TicketInput, TicketPrediction>>()
    .GetType(); // force pool init

// Reconfigure the pool to load from the trained model file
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

app.MapControllers();
app.Run();

